INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66765268', 66765268, 'analyze_legacy', 'Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN', 'central', 'Perwakilan BKKBN Provinsi Sumatera Selatan', 'Sewa Bandwidth Kantor Perwakilan', 'Jasa Lainnya', 'E-Purchasing', 'Sumatera Selatan, Palembang (Kota)', 239098000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', 'Bandwidth adalah kapasitas yang dapat digunakan pada kabel ethernet agar dapat dilewati trafik paket data dengan maksimal tertentu. Sewa Layanan bandwidth merupakan sarana pendukung pelaksanaan kegiatan di Kantor Perwakilan BKKBN Provinsi Sumatera Selatan.', 'Layanan Bandwidth yang dibutuhkan memiliki spesifikasi sebagai berikut: 1 Bandwith IP transit main link 200 Mbps dan back up 100 Mbps selama 12 bulan dengan CIR upstream dan downstream 1:1; 2 lnstalasi koneksi Layanan IP transit dengan menggunakan kabel fiber optic dan peremajaan infrasturtur jaringan seperti Router/Mikrotik, Akses Point dan RJ 45 Cat 6 yang dilakukan di Kantor Perwakilan BKKBN Provinsi Sumatera Selatan, Jl. Demang Lebar Daun No. 4266 Lorok Pakjo, Kecamatan Ilir Barat I, Kota Palembang, Sumatera Selatan, 30151; 3 Dukungan Corrective Maintenance, yaitu kegiatan perbaikan yang harus dilakukan oleh penyedia jasa apabila terjadi masalah pada koneksi jaringan Internet setelah menerima pemberitahuan gangguan dari Kantor Perwakilan BKKBN Provinsi Sumatera Selatan selama masa kontrak; 4 Sistem monitoring jaringan MRTG diberikan setiap bulan dan diberikan hak akses secara mandiri oleh penyedia; 5 SLA >= 99 % 6 Router yang seusai dengan kapasitas bandwidth 200 Mbps; 7 Akses Point telah support dengan fitur remote by cloud dengan beberapa titik di ruang kerja; 8 Tersedia Trial Jaringan sebagai salah satu pengujian serangkaian tes yang dilakukan oleh penyedia jasa terhadap perangkat untuk memastikan koneksi jaringan internet dapat bekerja dengan baik; 9 Pihak penyedia jasa melakukan pekerjaan design topologi jaringan, instalasi, testing dan commissioning serta melakukan layanan purna jual terhadap semua pekerjaan yang ditawarkan; 10 Penyedia jasa wajib memberikan informasi atas semua jasa dan perangkat yang akan ditawarkan. lnformasi tersebut termasuk design, rencana kerja dan jadwal, detail dari perangkat yang akan digunakan; 11 Dedicated on Demand yaitu ketersedian penyedia untuk menaikkan bandwidth jika tersedia event-event besar yang diadakan di Perwakilan BKKBN Provinsi Sumatera Selatan; 12 Penyedia jasa harus menyediakan dukungan teknis dan asistensi selama 24/7/360 dan tersedia jadwal rutin visitasi bulanan untuk memastikan kehandalan jaringan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2993637);
